hooks.command:
node -e 'try {
  const fs = require("node:fs");
  const { spawn } = require("node:child_process");
  const input = JSON.parse(fs.readFileSync(0, "utf8"));
  if (["clear", "resume"].includes(input.reason)) process.exit(0);
  if (!input.transcript_path) process.exit(0);
  const text = fs.readFileSync(input.transcript_path, "utf8").trim().split("\n")
    .map(line => JSON.parse(line)).filter(entry => entry.type === "assistant")
    .map(entry => Array.isArray(entry.message.content)
      ? entry.message.content.filter(block => block.type === "text").map(block => block.text).join(" ")
      : entry.message.content).join("\n");
  const summary = Array.from(text).slice(-1500).join("").replace(/\n/g, " ");
  if (summary.length < 20) process.exit(0);
  const env = { ...process.env,
    ENGRAM_DB_PATH: process.env.ENGRAM_DB_PATH || "~/.engram/engram.db",
    ENGRAM_SOURCE: process.env.ENGRAM_SOURCE || "claude-code"
  };
  const args = ["-y", "-p", "@engram-ai-memory/mcp@latest", "engram-store-session", "Session summary: " + summary];
  const reportLaunchError = err => console.error("[engram] Could not launch engram-store-session:", err.code || err.name);
  try {
    let command = "npx";
    if (process.platform === "win32") {
      const path = require("node:path");
      command = process.execPath;
      args.unshift(require.resolve(path.join(path.dirname(command), "node_modules", "npm", "bin", "npx-cli.js")));
    }
    const child = spawn(command, args, { detached: true, stdio: "ignore", env });
    child.once("error", reportLaunchError);
    child.unref();
  } catch (err) { reportLaunchError(err); }
} catch {}' >/dev/null || true
